    fun getCefrLevel(word: String): String {
        val lower = word.lowercase().trim()
        return when {
            a1Words.contains(lower) -> "A1"
            a2Words.contains(lower) -> "A2"
            lower.length <= 5 -> "B1"
            lower.length in 6..8 -> "B2"
            lower.length in 9..11 -> "C1"
            else -> "C2"
        }
    }

    fun analyzeText(
        text: String,
        customStopWords: Set<String> = emptySet(),
        filterMinFrequency: Int = 1,
        filterMinLength: Int = 2,
        filterMaxLength: Int = 30,
        filterCefr: String? = null,
        removeStopWords: Boolean = true
    ): AnalysisResult {
        if (text.isBlank()) {
            return AnalysisResult(0, 0, emptyList())
        }

        // Split text into sentences for context extraction
        val sentences = text.split(Regex("""(?<=[.!?])\s+"""))
            .map { it.trim().replace(Regex("""\s+"""), " ") }
            .filter { it.length > 10 }

        // Tokenize words
        val rawTokens = text.split(Regex("""[^a-zA-Z0-9'\-]+"""))
            .map { it.lowercase().trim('\'', '-', ' ') }
            .filter { it.length in filterMinLength..filterMaxLength }

        val totalWords = rawTokens.size
        if (totalWords == 0) {
            return AnalysisResult(0, 0, emptyList())
        }

        // Map lemmas and counts
        val lemmaCountMap = mutableMapOf<String, Int>()
        val lemmaDisplayMap = mutableMapOf<String, String>()
        val lemmaContextMap = mutableMapOf<String, String>()

        for (token in rawTokens) {
            if (token.length < filterMinLength || token.length > filterMaxLength) continue
            if (token.all { it.isDigit() }) continue
            if (removeStopWords && StopWords.isStopWord(token, customStopWords)) continue

            val lemma = Lemmatizer.getLemma(token)
            lemmaCountMap[lemma] = (lemmaCountMap[lemma] ?: 0) + 1

            if (!lemmaDisplayMap.containsKey(lemma) || token.length < lemmaDisplayMap[lemma]!!.length) {
                lemmaDisplayMap[lemma] = token
            }

            if (!lemmaContextMap.containsKey(lemma)) {
                val matchingSentence = sentences.find { s ->
                    s.contains(token, ignoreCase = true) || s.contains(lemma, ignoreCase = true)
                }
                if (matchingSentence != null) {
                    lemmaContextMap[lemma] = matchingSentence
                }
            }
        }

        val sortedEntries = lemmaCountMap.entries
            .filter { it.value >= filterMinFrequency }
            .sortedByDescending { it.value }

        val uniqueCount = sortedEntries.size

        val wordItems = sortedEntries.mapIndexed { index, entry ->
            val lemma = entry.key
            val freq = entry.value
            val displayWord = lemmaDisplayMap[lemma] ?: lemma
            val percentage = (freq.toFloat() / totalWords.toFloat()) * 100f
            val cefr = getCefrLevel(lemma)
            val context = lemmaContextMap[lemma] ?: "No context sentence available in text."

            WordItem(
                word = displayWord,
                lemma = lemma,
                frequency = freq,
                percentage = percentage,
                rank = index + 1,
                contextSentence = context,
                cefrLevel = cefr
            )
        }.filter { item ->
            filterCefr == null || filterCefr == "ALL" || item.cefrLevel.equals(filterCefr, ignoreCase = true)
        }

        return AnalysisResult(
            totalWords = totalWords,
            uniqueWords = uniqueCount,
            wordList = wordItems
        )
    }

    fun mergeWordLists(
        list1: List<WordItem>,
        list2: List<WordItem>
    ): List<WordItem> {
        val map = mutableMapOf<String, WordItem>()

        for (item in list1) {
            map[item.lemma] = item
        }

        for (item in list2) {
            val existing = map[item.lemma]
            if (existing != null) {
                val newFreq = existing.frequency + item.frequency
                val newContext = if (existing.contextSentence.isNotBlank()) existing.contextSentence else item.contextSentence
                map[item.lemma] = existing.copy(
                    frequency = newFreq,
                    contextSentence = newContext,
                    isLearned = existing.isLearned || item.isLearned,
                    isFavorite = existing.isFavorite || item.isFavorite,
                    translation = existing.translation ?: item.translation
                )
            } else {
                map[item.lemma] = item
            }
        }

        val totalFreq = map.values.sumOf { it.frequency }.toFloat().coerceAtLeast(1f)

        return map.values.sortedByDescending { it.frequency }.mapIndexed { index, item ->
            item.copy(
                rank = index + 1,
                percentage = (item.frequency.toFloat() / totalFreq) * 100f
            )
        }
    }
